async function resumeSession(){
 const response=await fetch('/auth/session',{credentials:'same-origin',cache:'no-store'});
 if(!response.ok)throw Error('Completa el inicio de sesión en la otra pestaña y pulsa Continuar.');
 const value=await response.json();
 if(!originalSubject||value.subject!==originalSubject)throw Error('Inicia sesión con la misma cuenta para guardar los cambios de este diagrama.');
 document.querySelector('meta[name=csrf-token]').content=value.csrf;
}
async function api(path='',options={},retried=false,base=API){
 const response=await fetch(base+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CSRF-Token':document.querySelector('meta[name=csrf-token]')?.content||'',...options.headers}});
 if(!response.ok){let body={};try{body=await response.json();}catch{}
  if(response.status===403&&body.code==='csrf_invalid'&&!retried){try{await resumeSession();return api(path,options,true,base);}catch{window.dispatchEvent(new Event('koodaria:auth-required'));}}
  if(response.status===401){
   if(!dirty&&!activeSaver?.isDirty())window.location.replace(loginUrl());
   else window.dispatchEvent(new Event('koodaria:auth-required'));
  }
  const error=new Error(body.error||'No se pudo conectar. Tus cambios siguen en esta pestaña.');error.status=response.status;throw error;
 }
 return response.status===204?null:response.json();
}
