 const create=async(name,templateId,standard)=>{setBusy(true);setError('');try{const value=await api('',{method:'POST',body:JSON.stringify({name,template_id:templateId,...(standard?{standard:{id:standard.id,version:standard.version}}:{}),folder_id:currentFolder?.id||null})});setCreateOpen(false);setItem(value);}catch(e){setError(e.message);}finally{setBusy(false);}};
