 if(item)return <><Editor key={item.id} item={item} standards={publications} onBack={back} onCopy={copy} pending={pending} outerError={error} reauth={reauth} onResume={recover} canCreate={caps.can_create} canShare={item.access==='owner'||(scope==='mine'&&caps.can_create)} onShare={()=>setShareTarget(item)}/>{shareTarget&&<ShareDialog key={shareTarget.id} target={shareTarget} onClose={()=>setShareTarget(null)}/>}</>;
