 {scope==='mine'&&currentFolder&&<div className="library-breadcrumb"><button onClick={()=>chooseFolder('root')}>Mis diagramas</button><span aria-hidden="true">/</span><span>{currentFolder.name}</span><button className="icon-button" title="Renombrar grupo" aria-label="Renombrar grupo" onClick={()=>editFolder(currentFolder)}><Glyph name="edit"/></button></div>}
